// fr contract (backend/src/services/conveyor-start-webhook.ts): body {event:"project.created", rm_project_id, tenant_id, fr_project_id}
// (+ restart for a member's restart) and header Idempotency-Key. 400 = fr sent a malformed start (never retried).
// R349: restart {scope:'project'} restarts at 'setup'; {scope:'phase', phase, comment?} restarts that RM phase (current or earlier).
const b = $json.body || {};
const h = $json.headers || {};
const S = (v) => (v === undefined || v === null) ? '' : String(v).trim();
const key = S(h['idempotency-key']);
if (b.event !== 'project.created' || S(b.rm_project_id) === '' || key === '') {
  return [{ json: { status: 400, body: { accepted: false, code: 'invalid_start_request', error: 'invalid_start_request' } } }];
}
let restart = null;
if (b.restart !== undefined && b.restart !== null) {
  const r = b.restart;
  const bad = [{ json: { status: 400, body: { accepted: false, code: 'restart_invalid', error: 'restart_invalid' } } }];
  if (typeof r !== 'object' || Array.isArray(r)) return bad;
  if (r.comment !== undefined && r.comment !== null && (typeof r.comment !== 'string' || r.comment.length > 2000)) return bad;
  const comment = S(r.comment);
  if (r.scope === 'project') restart = { scope: 'project', phase: 'setup', comment: comment };
  else if (r.scope === 'phase' && typeof r.phase === 'string' && r.phase.trim() !== '') restart = { scope: 'phase', phase: r.phase.trim(), comment: comment };
  else return bad;
}
return [{ json: { status: 0, rm_project_id: S(b.rm_project_id), tenant_id: S(b.tenant_id), fr_project_id: S(b.fr_project_id), idempotency_key: key, restart: restart } }];

// RM getProject (conveyor tenant). 404 = not a project of this tenant -> 409 project_mismatch (final).
// Any other failure (RM down, credential) -> 503 so fr retries. Then tenant, phase, board link.
// A restart (R349) skips the setup-phase check: Restart plan checks the target phase against the type's phase order.
const v = $('Validate').first().json;
const p = $json || {};
const refuse = (code) => [{ json: { status: 409, body: { accepted: false, code: code, error: code } } }];
if (p.error !== undefined || !p.id) {
  const msg = String((p.error && (p.error.message || p.error.description || p.error)) || p.message || '');
  if (p.error !== undefined && /404|not.?found/i.test(msg)) return refuse('project_mismatch');
  return [{ json: { status: 503, body: { accepted: false, code: 'start_unavailable', error: 'start_unavailable' } } }];
}
if (String(p.tenant_id || '') !== v.tenant_id) return refuse('tenant_mismatch');
if (v.fr_project_id !== '' && p.origin_project_id && String(p.origin_project_id) !== v.fr_project_id) return refuse('project_mismatch');
if (v.restart === null && String(p.current_phase || '') !== 'setup') return refuse('phase_not_setup');
const ids = p.planka_list_ids || {};
if (!p.planka_board_id || !ids.TODO || !ids.READY) return refuse('project_mismatch');
return [{ json: { status: 0, project_id: String(p.id), board_id: String(p.planka_board_id), todo_list_id: String(ids.TODO), ready_list_id: String(ids.READY), phase: String(p.current_phase || ''), project_type_id: String(p.project_type_id || '') } }];

// The existing start card IS the idempotency: one project_start_request_analysis card per board.
// Still in TODO -> 200 resumed after Move to READY moves it; anywhere else -> 409 psra_exists; none -> create it in TODO.
// The card carries the tenant (keycloak_tenant_id): the Planka webhook payload gives every downstream flow the
// card + the board's custom-field definitions, so this field is how a card flow knows which tenant it acts for.
// Omitted when the start carries no tenant rather than written as '': an empty value satisfies an existence
// check while failing every <> '' test, which is worse than an absent field.
const pc = $('Project checks').first().json;
const v = $('Validate').first().json;
const inc = ($json || {}).included || {};
if (!Array.isArray(inc.cards)) throw new Error('Get board returned no included.cards for board ' + pc.board_id);
const TYPE = 'project_start_request_analysis';
const fieldName = {};
(inc.customFields || []).forEach(f => { fieldName[String(f.id)] = f.name; });
const psraIds = new Set((inc.customFieldValues || [])
  .filter(x => fieldName[String(x.customFieldId)] === 'card_type' && String(x.content || '').trim() === TYPE)
  .map(x => String(x.cardId)));
const psra = inc.cards.filter(c => psraIds.has(String(c.id)));
if (psra.length) {
  if (psra.every(c => String(c.listId) === pc.todo_list_id)) return [{ json: { status: 200, card_id: String(psra[0].id), body: { accepted: true, resumed: true } } }];
  return [{ json: { status: 409, body: { accepted: false, code: 'psra_exists', error: 'psra_exists' } } }];
}
const fields = { card_type: TYPE, phase: pc.phase };
if (v.tenant_id) fields.keycloak_tenant_id = v.tenant_id;
return [{ json: { status: 0, list_id: pc.todo_list_id, name: 'Project start request analysis',
  description: 'Analyse the start request of RM project ' + pc.project_id + ' (fr project ' + v.fr_project_id + ').',
  custom_fields: JSON.stringify(fields) } }];

// The card must exist AND carry card_type, or wip.pull can never see it: a lost card_type fails the run (fr retries on 5xx).
const out = $json || {};
const lost = Array.isArray(out.customFieldsNotPersisted) ? out.customFieldsNotPersisted : Object.keys(out.customFieldsNotPersisted || {});
const lostNames = lost.map(n => (n !== null && typeof n === 'object') ? String(n.name || '') : String(n));
if (!out.item || !out.item.id) throw new Error('Set card fields returned no card');
if (lostNames.indexOf('card_type') >= 0) throw new Error('card_type was not persisted on card ' + out.item.id);
const r = $('Validate').first().json.restart;
return [{ json: { status: 200, card_id: String(out.item.id), body: r ? { accepted: true, restarted: true, phase: r.phase } : { accepted: true } } }];

// The start card is structural (no WIP slot): conveyor.start moves it TODO -> READY itself, which fires its READY flow.
// A failed move fails the run (n8n answers 5xx, fr retries; the retry finds the card still in TODO and moves it).
const out = $json || {};
const pc = $('Project checks').first().json;
if (!out.item || String(out.item.listId) !== pc.ready_list_id) throw new Error('Move to READY did not land card ' + String((out.item || {}).id || '') + ' in READY');
const src = $('Created').isExecuted ? $('Created').first().json : $('Start decision').first().json;
return [{ json: { status: 200, card_id: String(out.item.id), body: src.body } }];

// R349 restart. The target phase must be one of the project type's phases (by position) and not after the current
// phase, else 409 restart_phase_invalid. Every card of the target phase or a later one (its `phase` field; scope
// project = every card) leaves the flow: one item per card for Archive card -> the board's Planka archive list.
// Board get lists only active/closed-list cards, so archived cards never reach a board reader again, and a move into
// the archive list fires no flow (its list has no name, so the per-flow webhook URL has no {list} and is skipped).
const v = $('Validate').first().json;
const pc = $('Project checks').first().json;
const r = v.restart;
const t = $('Project type').first().json || {};
const inc = ($('Get board').first().json || {}).included || {};
if (!Array.isArray(inc.cards)) throw new Error('Get board returned no included.cards for board ' + pc.board_id);
const refuse = (code) => [{ json: { status: 409, body: { accepted: false, code: code, error: code } } }];
const list = Array.isArray(t.phases) ? t.phases.slice() : [];
if (list.length === 0) throw new Error('Restart plan: project type ' + pc.project_type_id + ' returned no phases');
list.sort((a, b) => Number(a.position) - Number(b.position));
const phases = list.map(x => String(x.name));
const ti = phases.indexOf(r.phase);
const ci = phases.indexOf(pc.phase);
if (ti < 0 || ci < 0 || ti > ci) return refuse('restart_phase_invalid');
const archive = (inc.lists || []).find(l => l.type === 'archive');
if (!archive) throw new Error('Restart plan: board ' + pc.board_id + ' has no archive list');
const later = new Set(phases.slice(ti));
const nameOf = {};
(inc.customFields || []).forEach(f => { nameOf[String(f.id)] = String(f.name); });
const phaseOf = {};
(inc.customFieldValues || []).forEach(x => { if (nameOf[String(x.customFieldId)] === 'phase') phaseOf[String(x.cardId)] = String(x.content || '').trim(); });
const out = inc.cards
  .filter(c => r.scope === 'project' || later.has(phaseOf[String(c.id)]))
  .map(c => ({ json: { status: 0, card_id: String(c.id), archive_list_id: String(archive.id), phase: r.phase, current_phase: pc.phase } }));
if (out.length === 0) return [{ json: { status: 0, card_id: null, archive_list_id: String(archive.id), phase: r.phase, current_phase: pc.phase } }];
return out;

// Every archived card must have landed in the archive list, or the restart stops (n8n answers 5xx, fr retries).
const want = $('Restart plan').first().json.archive_list_id;
const bad = $input.all().map(i => i.json || {}).filter(o => !o.item || String(o.item.listId) !== want);
if (bad.length) throw new Error('Archive card did not land ' + bad.length + ' card(s) in the archive list');
return [{ json: { archived: $input.all().length } }];

// R349: the restarted phase's start card, created in TODO and moved to READY exactly as a fresh start.
// setup -> project_start_request_analysis; any other phase -> project_phase_start. The member's comment steers it.
// It carries the tenant (keycloak_tenant_id) like any start card, so the card flows keep acting for the right tenant.
const v = $('Validate').first().json;
const pc = $('Project checks').first().json;
const r = v.restart;
const setup = r.phase === 'setup';
const TYPE = setup ? 'project_start_request_analysis' : 'project_phase_start';
const base = setup
  ? 'Analyse the start request of RM project ' + pc.project_id + ' (fr project ' + v.fr_project_id + ').'
  : 'Start phase ' + r.phase + ' of RM project ' + pc.project_id + ' (fr project ' + v.fr_project_id + ') again (restart).';
const steer = r.comment ? '\n\n## Steering comment (restart)\n' + r.comment : '';
const fields = { card_type: TYPE, phase: r.phase };
if (v.tenant_id) fields.keycloak_tenant_id = v.tenant_id;
return [{ json: { status: 0, list_id: pc.todo_list_id,
  name: setup ? 'Project start request analysis' : 'Project phase start: ' + r.phase,
  description: base + steer,
  custom_fields: JSON.stringify(fields) } }];
